    {
      "@id": "activity:translation-pages_originstorypage.the_first_part_was_solved_by_smartphones-2026-11-25T18:15:22.616743+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-25T18:15:22.616743+00:00",
